  "sql": "SELECT cs.canonical_smiles, r_sub.compound_name AS substrate_compound_name, r_par.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_records r_sub ON m.substrate_record_id = r_sub.record_id JOIN compound_records r_par ON m.drug_record_id = r_par.record_id JOIN molecule_hierarchy mh ON r_par.molregno = mh.molregno JOIN compound_structures cs ON mh.active_molregno = cs.molregno WHERE m.organism = 'Callithrix jacchus' ORDER BY cs.canonical_smiles, r_sub.compound_name, r_par.compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name LIMIT 200"
